/// Word-start matcher shared by the palette and its regression
/// tests: every whitespace-separated query token must prefix-match
/// a word start in the entry kind id or label. Substring hits like
/// 'row' in Breadcrumb's 'arrow' separator text no longer match.
bool registryMatchesQuery(RegistryEntry entry, String query) {
  final tokens = query
      .trim()
      .toLowerCase()
      .split(RegExp(r'\s+'))
      .where((t) => t.isNotEmpty)
      .toList();
  if (tokens.isEmpty) return true;
  final words = entry.kind
      .toLowerCase()
      .split(RegExp(r'[^a-z0-9]+'))
      .where((w) => w.isNotEmpty)
      .toList();
  // Tile labels are prettified kind ids ([_tileLabel] in the palette), so
  // matching kind-id words is exactly what the user sees. Descriptions are
  // deliberately NOT matched — 'chips' in a Filter Bar blurb must not make
  // it match 'chip'.
  return tokens.every((t) => words.any((w) => w.startsWith(t)));
}

/// Visible entries for [section] in registry order (hidden
/// utilities excluded — the palette renders sections from this).
List<RegistryEntry> registrySectionEntries(String section) {
  return [
    for (final entry in kRegistry)
      if (entry.section == section &&
          !kHiddenUtilityKinds.contains(entry.kind))
        entry,
  ];
}

/// Looks up a registry entry by kind, or null when unknown.
RegistryEntry? findRegistryEntry(String kind) {
  for (final entry in kRegistry) {
    if (entry.kind == kind) return entry;
  }
  return null;
}

