/// Dashed rounded-rectangle painter for [RegistryPlaceholder].
class _DashPainter extends CustomPainter {
  final Color color;

  const _DashPainter({required this.color});

  static const _dash = 5.0;
  static const _gap = 3.0;
  static const _radius = 8.0;

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1;
    final rect = Offset.zero & size;
    final path = Path()
      ..addRRect(RRect.fromRectAndRadius(rect, const Radius.circular(_radius)));
    final metrics = path.computeMetrics().single;
    var distance = 0.0;
    while (distance < metrics.length) {
      final end = (distance + _dash).clamp(0.0, metrics.length);
      canvas.drawPath(metrics.extractPath(distance, end), paint);
      distance += _dash + _gap;
    }
  }

  @override
  bool shouldRepaint(covariant _DashPainter oldDelegate) =>
      oldDelegate.color != color;
}
