Widget buildTextAreaEntry(Map<String, dynamic> props) {
  final placeholder = (props['placeholder'] ?? 'Type here') as String;
  final label = (props['label'] ?? '') as String;
  final disabled = (props['disabled'] ?? false) as bool;
